/**
 * The inbox's sounds, base64-encoded rather than shipped as files.
 *
 * Three 8-bit mono WAVs, ~50KB in total. Inlined because the package is built by
 * svelte-package and bundled by `bun build` for the CLI, and neither is guaranteed to carry
 * a binary asset through to `dist` — a sound that silently stops existing once published is
 * worse than an ugly constant.
 */

/** WAV bytes by name, base64. Served by the inbox at `/__postboi/api/sounds/:name`. */
export const SOUNDS: Record<string, string> = {
	welcome:
		"",
	mail: "",
	goodbye:
		"",
}
